export function presetSlugToId(slug: string): string {
  return slug.replace(/-/g, '_')
}

export const bySlug: Record<string, CaptionPreset> = Object.fromEntries(
  CAPTION_PRESETS.map((p) => [p.slug, p]),
)

export const byId: Record<string, CaptionPreset> = Object.fromEntries(
  CAPTION_PRESETS.map((p) => [presetSlugToId(p.slug), p]),
)

export function resolvePreset(presetId?: string | null): CaptionPreset {
  const id = presetId?.trim() || 'bold_pop'
  return byId[id] ?? byId.bold_pop ?? CAPTION_PRESETS[0]
}

function nonNullConfigValue(v: unknown): boolean {
  return v !== null && v !== undefined && v !== ''
}

/** Merge preset JSON with edits.captions.presetConfig (same rule as worker build_ass). */
export function resolveCaptionPreset(cap: ClipEditsV2['captions'] | undefined): CaptionPreset {
  const preset = resolvePreset(cap?.presetId)
  let base = cap?.font?.trim() ? { ...preset, font: cap.font.trim() } : preset
  const cfg = cap?.presetConfig
  if (!cfg || typeof cfg !== 'object') return base
  const merged = { ...base } as Record<string, unknown>
  for (const [k, v] of Object.entries(cfg as Record<string, unknown>)) {
    if (nonNullConfigValue(v)) merged[k] = v
  }
  return merged as CaptionPreset
}
